1	const PROCESSING_FEE = 5;
2	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
3	const BLOCK_SIZE = 3;
4	const BLOCK_DISCOUNT_PERCENT = 20;
5	const CURSE_SURCHARGE_PERCENT = 50;
6	const HIGH_ENCHANTMENT_THRESHOLD = 5;
7	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
8	const LOYALTY_YEARS_THRESHOLD = 2;
9	const LOYALTY_DISCOUNT_PERCENT = 20;
10	const FOLLOW_UP_DISCOUNT_PERCENT = 15;
11	const DEDUCTIBLE = 100;
12	const CAP_MULTIPLE = 2;
13	// The CLAIM_ prefix marks the claim-side pair. Both are deliberately distinct
14	// from their premium-side namesakes above: a sword can be enchanted enough to
15	// cost more to insure (threshold 5) without being enchanted enough to pay out
16	// less (threshold 8).
17	const CLAIM_HIGH_ENCHANTMENT_THRESHOLD = 8;
18	const CLAIM_HIGH_ENCHANTMENT_REIMBURSEMENT_PERCENT = 50;
19	
20	const BASE_PREMIUMS = {
21	  sword: 100,
22	  amulet: 60,
23	  staff: 80,
24	  potion: 40,
25	  rune: 25,
26	  moonstone: 25,
27	} as const;
28	
29	// What an item is insured FOR, as opposed to what insuring it costs. The cap on
30	// claims is derived from these, so premium discounts never move it.
31	const INSURANCE_VALUES = {
32	  sword: 1000,
33	  amulet: 600,
34	  staff: 800,
35	  potion: 400,
36	  rune: 250,
37	  moonstone: 250,
38	} as const;
39	
40	// The six priced types are the domain, so they are derived from the premium
41	// table rather than restated: a type nobody prices cannot be insured. The
42	// unknown-type case (broomstick) is still a runtime error the tests will drive.
43	type ItemType = keyof typeof BASE_PREMIUMS;
44	
45	// Components (as opposed to main items) are the only things the block rule
46	// applies to, so the distinction has to be data, not a price coincidence.
47	// Typed as a set of ItemType so a component can never name an unpriced type.
48	const COMPONENT_TYPES = new Set<ItemType>(["rune", "moonstone"]);
49	
50	const PERCENT_WHOLE = 100;
51	
52	// Divides rather than multiplying by a rate: `amount * 1.1` introduces
53	// floating-point error that shifts the spec's round-up in MHPCO's favour.
54	const percentOf = (percent: number, amount: number): number =>
55	  (amount * percent) / PERCENT_WHOLE;
56	
57	// MHPCO rounds every money amount in its own favour: premiums (customer pays)
58	// round up, payouts (MHPCO pays) round down.
59	const roundPremiumInMHPCOsFavour = Math.ceil;
60	
61	export type QuoteResult = { premium: number };
62	
63	export type ClaimResult = { payout: number; remainingCap: number };
64	
65	export type ScenarioResult = QuoteResult | ClaimResult;
66	
67	// `material` is still unread — the dragon-material claim clause will reach for
68	// it. All three are optional so a bare `{ type: "rune" }` typechecks: a rune has
69	// no enchantment to speak of, rather than an enchantment of zero.
70	type Item = {
71	  type: ItemType;
72	  material?: string;
73	  enchantment?: number;
74	  cursed?: boolean;
75	};
76	
77	type Damage = { itemType: string; amount: number };
78	
79	type Incident = { cause: string; damages: Damage[] };
80	
81	type QuoteStep = { op: "quote"; items: Item[] };
82	
83	type ClaimStep = { op: "claim"; policy: number; incident: Incident };
84	
85	type Step = QuoteStep | ClaimStep;
86	
87	const isQuote = (step: Step): step is QuoteStep => step.op === "quote";
88	
89	type Customer = { yearsWithMHPCO: number };
90	
91	type Scenario = {
92	  customer: Customer;
93	  steps: Step[];
94	};
95	
96	const sum = (amounts: number[]): number =>
97	  amounts.reduce((total, amount) => total + amount, 0);
98	
99	const basePremiumForItem = (item: Item): number => BASE_PREMIUMS[item.type];
100	
101	const sumBasePremiums = (items: Item[]): number => sum(items.map(basePremiumForItem));
102	
103	// Groups of items that are "alike" — same type. The type is kept alongside the
104	// items because the block rule asks about it; recovering it from items[0] would
105	// make every reader re-derive that a group is non-empty and homogeneous.
106	type AlikeItems = { type: ItemType; items: Item[] };
107	
108	const groupByType = (items: Item[]): AlikeItems[] => {
109	  const groups = new Map<ItemType, Item[]>();
110	  for (const item of items) {
111	    const group = groups.get(item.type) ?? [];
112	    group.push(item);
113	    groups.set(item.type, group);
114	  }
115	  return [...groups].map(([type, groupedItems]) => ({ type, items: groupedItems }));
116	};
117	
118	// A block is a discount on the components' combined base premium, not a flat
119	// price: 3 runes are 75 G less 20 % = 60 G. Derived rather than hardcoded so the
120	// 20 % stays visible as the rule it is.
121	const blockBasePremium = (items: Item[]): number => {
122	  const undiscounted = sumBasePremiums(items);
123	  return undiscounted - percentOf(BLOCK_DISCOUNT_PERCENT, undiscounted);
124	};
125	
126	// Exactly BLOCK_SIZE, not "at least": 4 or 7 runes form no block, so a bigger
127	// pile is never cheaper than the block it contains. Components only — three
128	// swords are three separate insurances, not a discounted building block.
129	const formsABlock = ({ type, items }: AlikeItems): boolean =>
130	  items.length === BLOCK_SIZE && COMPONENT_TYPES.has(type);
131	
132	const basePremiumForGroup = (alikeItems: AlikeItems): number =>
133	  formsABlock(alikeItems)
134	    ? blockBasePremium(alikeItems.items)
135	    : sumBasePremiums(alikeItems.items);
136	
137	// Priced per group of alike items rather than over the whole list, so 3 runes
138	// and 3 moonstones each form their own block.
139	const policyBasePremiumFor = (items: Item[]): number =>
140	  sum(groupByType(items).map(basePremiumForGroup));
141	
142	const percentOfWhen = (applies: boolean, percent: number, amount: number): number =>
143	  applies ? percentOf(percent, amount) : 0;
144	
145	// Each item-specific surcharge is a percentage of the affected item's OWN base
146	// premium, so every rule reads as "this much, when this holds". The terms are
147	// summed rather than chosen between: an item can trigger several at once.
148	//
149	// Deliberately two explicit terms rather than a table of rules. The shared
150	// shape is only the arithmetic tail; the conditions differ in kind (a flag vs.
151	// a threshold over an optional number), and nothing in the remaining spec adds
152	// a third item-specific surcharge to generalise over.
153	const surchargeFor = (item: Item): number => {
154	  const base = basePremiumForItem(item);
155	  return (
156	    percentOfWhen(item.cursed === true, CURSE_SURCHARGE_PERCENT, base) +
157	    percentOfWhen(
158	      (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
159	      HIGH_ENCHANTMENT_SURCHARGE_PERCENT,
160	      base,
161	    )
162	  );
163	};
164	
165	// Charged alongside the policy base premium — never folded into it, or the
166	// policy-wide modifiers would compound on top of them.
167	const itemSurchargesFor = (items: Item[]): number => sum(items.map(surchargeFor));
168	
169	// Unlike the item-specific surcharges, these are percentages of the WHOLE
170	// policy's base premium. Each is returned already signed — a surcharge is
171	// positive, a discount negative — so the rule and its direction stay on one
172	// line instead of the sign living in a `+`/`-` further down the sum.
173	const policyModifiersFor = (
174	  policyBasePremium: number,
175	  customer: Customer,
176	  isFollowUpContract: boolean,
177	): number[] => [
178	  // Applies to every quote, follow-ups included: the spec treats each item in a
179	  // quote as newly insured, regardless of how long the customer has been around.
180	  percentOf(FIRST_INSURANCE_SURCHARGE_PERCENT, policyBasePremium),
181	  -percentOfWhen(
182	    customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD,
183	    LOYALTY_DISCOUNT_PERCENT,
184	    policyBasePremium,
185	  ),
186	  -percentOfWhen(isFollowUpContract, FOLLOW_UP_DISCOUNT_PERCENT, policyBasePremium),
187	];
188	
189	// The order of the terms is the order of the spec's rules: what the items are
190	// worth, what they individually cost extra, what the policy as a whole is
191	// adjusted by, and MHPCO's fee on top.
192	const quoteFor = (
193	  items: Item[],
194	  customer: Customer,
195	  isFollowUpContract: boolean,
196	): QuoteResult => {
197	  const policyBasePremium = policyBasePremiumFor(items);
198	  const premium = roundPremiumInMHPCOsFavour(
199	    policyBasePremium +
200	      itemSurchargesFor(items) +
201	      sum(policyModifiersFor(policyBasePremium, customer, isFollowUpContract)) +
202	      PROCESSING_FEE,
203	  );
204	  return { premium };
205	};
206	
207	// A follow-up contract is any quote after the customer's first, so what counts
208	// is how many QUOTES precede this step — not how many steps do. Claim steps sit
209	// in the same list and must not push a later quote into follow-up territory.
210	const isFollowUpContract = (precedingSteps: Step[]): boolean =>
211	  precedingSteps.some(isQuote);
212	
213	const insuranceSumFor = (items: Item[]): number =>
214	  sum(items.map((item) => INSURANCE_VALUES[item.type]));
215	
216	// MHPCO pays, so payouts round down.
217	const roundPayoutInMHPCOsFavour = Math.floor;
218	
219	// Each damage entry carries its own deductible: one dragon attack damaging two
220	// items is two damages, and MHPCO withholds 100 G from each. The reimbursement
221	// clauses apply to the damage amount FIRST, so the deductible bites last.
222	const payoutForDamage = (damage: Damage, damagedItem: Item): number => {
223	  const reimbursable =
224	    (damagedItem.enchantment ?? 0) >= CLAIM_HIGH_ENCHANTMENT_THRESHOLD
225	      ? percentOf(CLAIM_HIGH_ENCHANTMENT_REIMBURSEMENT_PERCENT, damage.amount)
226	      : damage.amount;
227	  return reimbursable - DEDUCTIBLE;
228	};
229	
230	// Which insured item a damage entry refers to, since the reimbursement clauses
231	// depend on that item's enchantment and material. Nothing validates that the
232	// policy actually covers the damaged type yet; the error-case tests will turn
233	// this throw into a reported error.
234	const damagedItemFor = (damage: Damage, insuredItems: Item[]): Item => {
235	  const item = insuredItems.find((insured) => insured.type === damage.itemType);
236	  if (item === undefined) {
237	    throw new Error(`Claim damages a ${damage.itemType}, which this policy does not cover`);
238	  }
239	  return item;
240	};
241	
242	// The cap is a property of the POLICY, not of the claim: twice what the policy's
243	// items are insured for. Kept separate from the payout so the cross-claim
244	// accumulation the spec still demands has an obvious place to attach.
245	const capFor = (policy: QuoteStep): number =>
246	  insuranceSumFor(policy.items) * CAP_MULTIPLE;
247	
248	const claimFor = (claim: ClaimStep, policy: QuoteStep): ClaimResult => {
249	  const payout = roundPayoutInMHPCOsFavour(
250	    sum(
251	      claim.incident.damages.map((damage) =>
252	        payoutForDamage(damage, damagedItemFor(damage, policy.items)),
253	      ),
254	    ),
255	  );
256	  return { payout, remainingCap: capFor(policy) - payout };
257	};
258	
259	// `claim.policy` indexes the scenario's steps, and the referenced step must be a
260	// quote — a claim against a claim is meaningless. Nothing validates the scenario
261	// yet, so this states the assumption instead of casting past it; the
262	// error-case tests will turn the throw into a reported error.
263	const policyReferencedBy = (claim: ClaimStep, steps: Step[]): QuoteStep => {
264	  const step = steps[claim.policy];
265	  if (step === undefined || !isQuote(step)) {
266	    throw new Error(`Claim references step ${claim.policy}, which is not a quote`);
267	  }
268	  return step;
269	};
270	
271	export const runScenario = (scenario: Scenario): { results: ScenarioResult[] } => {
272	  const results = scenario.steps.map((step, stepIndex) =>
273	    isQuote(step)
274	      ? quoteFor(
275	          step.items,
276	          scenario.customer,
277	          isFollowUpContract(scenario.steps.slice(0, stepIndex)),
278	        )
279	      : claimFor(step, policyReferencedBy(step, scenario.steps)),
280	  );
281	  return { results };
282	};
